'use strict';
// Moving the preview leaves the capture/processing pipeline untouched.
const cameraWindow=$('cameraWindow'),cameraHandle=$('cameraWindowHandle'),cameraHome=cameraWindow.parentElement,cameraHomeSibling=cameraWindow.nextSibling;let cameraWindowPlacement=null,cameraWindowPlaceholder=null,cameraWindowDrag=null;
function placeCameraWindow(){if(!cameraWindowPlacement)return;const p=cameraWindowPlacement,maxWidth=Math.max(180,Math.min(window.innerWidth-16,(window.innerHeight-50)*1.5));p.width=Math.min(maxWidth,p.width);cameraWindow.style.width=p.width+'px';const h=cameraWindow.getBoundingClientRect().height;p.left=Math.max(8,Math.min(window.innerWidth-p.width-8,p.left));p.top=Math.max(8,Math.min(window.innerHeight-h-8,p.top));cameraWindow.style.left=p.left+'px';cameraWindow.style.top=p.top+'px';}
function floatCameraWindow(){if(cameraWindowPlacement)return;const r=cameraWindow.getBoundingClientRect();cameraWindowPlaceholder=document.createElement('div');cameraWindowPlaceholder.className='monitorPlaceholder';cameraWindowPlaceholder.style.height=r.height+'px';cameraWindowPlaceholder.textContent='Camera preview is floating. Drag its header or click Dock.';cameraWindow.before(cameraWindowPlaceholder);document.body.appendChild(cameraWindow);cameraWindow.classList.add('floatingCamera');cameraWindowPlacement={left:r.left,top:r.top,width:r.width};placeCameraWindow();}
function saveCameraWindow(){try{if(cameraWindowPlacement)localStorage.setItem('visual-rig-camera-window',JSON.stringify(cameraWindowPlacement));else localStorage.removeItem('visual-rig-camera-window');}catch{}}
$('dockCamera').onclick=()=>{if(!cameraWindowPlacement)return;cameraWindowPlaceholder.replaceWith(cameraWindow);cameraWindowPlaceholder=null;cameraWindowPlacement=null;cameraWindow.classList.remove('floatingCamera');cameraWindow.style.width='';cameraWindow.style.left='';cameraWindow.style.top='';saveCameraWindow();};
cameraHandle.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;e.preventDefault();floatCameraWindow();cameraWindowDrag={x:e.clientX,y:e.clientY,left:cameraWindowPlacement.left,top:cameraWindowPlacement.top};cameraHandle.setPointerCapture(e.pointerId);});cameraHandle.addEventListener('pointermove',e=>{if(!cameraWindowDrag)return;cameraWindowPlacement.left=cameraWindowDrag.left+e.clientX-cameraWindowDrag.x;cameraWindowPlacement.top=cameraWindowDrag.top+e.clientY-cameraWindowDrag.y;placeCameraWindow();});cameraHandle.addEventListener('pointerup',()=>{cameraWindowDrag=null;saveCameraWindow();});cameraHandle.addEventListener('pointercancel',()=>{cameraWindowDrag=null;saveCameraWindow();});window.addEventListener('resize',()=>{placeCameraWindow();saveCameraWindow();});
